#!/usr/bin/env node
// Differential test harness: compares a Node port against the reference executable.
// Usage: node /tmp/difftest.mjs /output/test11.mjs
// Zero external dependencies, ESM only.

import { spawnSync } from 'node:child_process';
import { basename } from 'node:path';
import { pathToFileURL } from 'node:url';

export const REFERENCE = '/workspace/dataset/test11_executable';
export const REFERENCE_PROG = 'test11_executable';

// ---------------------------------------------------------------------------
// helpers for building exotic argv values while keeping this file ASCII-safe
// ---------------------------------------------------------------------------
const cp = (...codes) => codes.map((c) => String.fromCodePoint(c)).join('');

const ARABIC_5 = '٥';           // U+0665 ARABIC-INDIC DIGIT FIVE      -> 5
const ARABIC_6 = '٦';           // U+0666 ARABIC-INDIC DIGIT SIX       -> 6
const EXT_ARABIC_5 = '۵';       // U+06F5 EXTENDED ARABIC-INDIC FIVE   -> 5
const FULLWIDTH_1 = '１';        // U+FF11 FULLWIDTH DIGIT ONE          -> 1
const FULLWIDTH_2 = '２';        // U+FF12 FULLWIDTH DIGIT TWO          -> 2
const MATH_5 = cp(0x1d7dd);          // U+1D7DD MATH DOUBLE-STRUCK FIVE     -> 5 (astral Nd)
const DESERET_A = cp(0x10400);       // U+10400 DESERET CAPITAL LONG I      -> printable astral
const SUPERSCRIPT_2 = '²';      // category No -> rejected by int()

// ---------------------------------------------------------------------------
// CASES
// Every numeric magnitude stays <= 200 so no case loops for long.
// ---------------------------------------------------------------------------
export const CASES = [
  // --- normal values -------------------------------------------------------
  ['--a', '2', '--b', '3'],
  ['--a', '0', '--b', '0'],
  ['--a', '1', '--b', '0'],
  ['--a', '0', '--b', '1'],
  ['--a', '1', '--b', '1'],
  ['--a', '10', '--b', '7'],
  ['--a', '50', '--b', '25'],
  ['--a', '200', '--b', '0'],
  ['--a', '0', '--b', '200'],
  ['--a', '100', '--b', '100'],
  ['--b', '3', '--a', '2'],
  ['--b', '0', '--a', '0'],

  // --- negatives and mixed signs that cancel -------------------------------
  ['--a', '-3', '--b', '2'],
  ['--a', '2', '--b', '-3'],
  ['--a', '-5', '--b', '5'],
  ['--a', '5', '--b', '-5'],
  ['--a', '-1', '--b', '0'],
  ['--a', '0', '--b', '-1'],
  ['--a', '-7', '--b', '-8'],
  ['--a', '-200', '--b', '5'],
  ['--a', '5', '--b', '-200'],
  ['--a', '-1', '--b', '1'],
  ['--a', '3', '--b', '-2'],

  // --- "=" form ------------------------------------------------------------
  ['--a=2', '--b=3'],
  ['--a=0', '--b=0'],
  ['--a=-3', '--b=2'],
  ['--a=2', '--b', '3'],
  ['--a', '2', '--b=3'],
  ['--a=+5', '--b=007'],
  ['--a=-0', '--b=0'],

  // --- repeats overwrite ---------------------------------------------------
  ['--a', '1', '--a', '2', '--b', '3'],
  ['--a', '1', '--b', '1', '--b', '4'],
  ['--a', '1', '--a', '2', '--a', '3', '--b', '0'],
  ['--a=1', '--a=2', '--b=2'],
  ['--a', '5', '--b', '5', '--a', '-5'],

  // --- help flags (including unambiguous prefixes) -------------------------
  ['-h'],
  ['--help'],
  ['--h'],
  ['--he'],
  ['--hel'],
  ['--a', '3', '--b', '2', '-h'],
  ['-h', '--a', '3'],
  ['-h', '--c', '3'],
  ['--help', 'extra'],
  ['--a', '1', '--b', '2', '--c', '3', '-h'],
  ['--help', '--help'],

  // --- missing required (all three shapes) ---------------------------------
  [],
  ['--a', '1'],
  ['--b', '1'],
  ['--a=1'],
  ['--b=1'],

  // --- invalid ints --------------------------------------------------------
  ['--a', 'x', '--b', '1'],
  ['--a', '1.5', '--b', '1'],
  ['--a', '0x10', '--b', '1'],
  ['--a', '0b101', '--b', '1'],
  ['--a', '1e3', '--b', '1'],
  ['--a', '', '--b', '1'],
  ['--a', '_10', '--b', '1'],
  ['--a', '10_', '--b', '1'],
  ['--a', '1__0', '--b', '1'],
  ['--a', '+_5', '--b', '1'],
  ['--a', '- 5', '--b', '1'],
  ['--a', '5 5', '--b', '1'],
  ['--a', '+', '--b', '1'],
  ['--a', '-', '--b', '1'],
  ['--a', '   ', '--b', '1'],
  ['--a', SUPERSCRIPT_2, '--b', '1'],
  ['--a', '1', '--b', 'x'],
  ['--a', '1', '--b', '1.5'],
  ['--a', '1', '--b', ''],
  ['--a=', '--b', '1'],
  ['--a', '1', '--b='],

  // --- valid exotic ints ---------------------------------------------------
  ['--a', '1_0', '--b', '1'],
  ['--a', ' 5 ', '--b', '1'],
  ['--a', '+5', '--b', '1'],
  ['--a', '007', '--b', '1'],
  ['--a', ARABIC_5, '--b', '1'],
  ['--a', FULLWIDTH_1 + FULLWIDTH_2, '--b', '1'],
  ['--a', ARABIC_5 + '_' + ARABIC_6, '--b', '1'],
  ['--a', ARABIC_5 + '5', '--b', '1'],
  ['--a', EXT_ARABIC_5, '--b', '1'],
  ['--a', MATH_5, '--b', '1'],
  ['--a', '9' + MATH_5, '--b', '2'],
  ['--a', '-' + ARABIC_5, '--b', '5'],

  // --- whitespace padding accepted by Python str.strip() -------------------
  ['--a', ' 5 ', '--b', '1'],  // NBSP
  ['--a', ' 5 ', '--b', '1'],  // LINE SEP / PARA SEP
  ['--a', '5 ', '--b', '1'],  // VT / FF
  ['--a', '　5　', '--b', '1'],  // IDEOGRAPHIC SPACE
  ['--a', ' 5', '--b', '1'],        // OGHAM SPACE MARK
  ['--a', ' 5 ', '--b', '1'],  // MMSP / NNBSP
  ['--a', '5', '--b', '1'],        // NEL
  ['--a', ' 5 ', '--b', '1'],  // EN QUAD / HAIR SPACE
  ['--a', '\t5\n', '--b', '1'],
  ['--a', '\r5\r', '--b', '1'],

  // --- whitespace-looking chars that are NOT Python whitespace -> rejected --
  ['--a', '​5', '--b', '1'],        // ZWSP
  ['--a', '﻿5', '--b', '1'],        // BOM
  ['--a', '5', '--b', '1'],        // FILE SEPARATOR
  ['--a', '5', '--b', '1'],        // UNIT SEPARATOR
  ['--a', '5​', '--b', '1'],

  // --- repr()-exercising invalid values ------------------------------------
  ['--a', "it's", '--b', '1'],
  ['--a', 'both\'and"', '--b', '1'],
  ['--a', 'he said "hi"', '--b', '1'],
  ['--a', '\\back', '--b', '1'],
  ['--a', 'a\\\\b', '--b', '1'],
  ['--a', '\n', '--b', '1'],
  ['--a', '\t', '--b', '1'],
  ['--a', '\r', '--b', '1'],
  ['--a', '', '--b', '1'],         // -> \x0b
  ['--a', ' ', '--b', '1'],         // -> \x0c
  ['--a', '', '--b', '1'],         // -> \x01
  ['--a', ' ', '--b', '1'],         // -> \xa0
  ['--a', ' ', '--b', '1'],         // ->
  ['--a', '﻿', '--b', '1'],         // ->
  ['--a', '', '--b', '1'],         // ->  (Co)
  ['--a', '￾', '--b', '1'],         // -> ￾ (Cn)
  ['--a', 'é±', '--b', '1'],   // e-acute, plus-minus: printable
  ['--a', DESERET_A, '--b', '1'],        // printable astral, passes through
  ['--a', DESERET_A + '', '--b', '1'],
  ['--a', 'a\nb', '--b', '1'],
  ['--a', "q\\'w\"e", '--b', '1'],
  ['--a', "'", '--b', '1'],
  ['--a', '"', '--b', '1'],
  ['--a', '\'"', '--b', '1'],

  // --- unrecognized arguments ----------------------------------------------
  ['--a', '1', '--b', '2', '--c', '3'],
  ['--a', '1', '--b', '2', 'extra'],
  ['--a', '1', '--b', '2', '--'],
  ['--a', '1', '--b', '2', 'x', 'y', 'z'],
  ['--a', '1', '--b', '2', '--c'],
  ['extra', '--a', '1', '--b', '2'],
  ['--a', '1', '--b', '2', '-z'],
  ['--a', '1', '--b', '2', '--c=3'],
  ['--a', '1', '--b', '2', '--a-long', '4'],

  // --- expected one argument ------------------------------------------------
  ['--a', '--b', '1'],
  ['--a', '1', '--b'],
  ['--a'],
  ['--b'],
  ['--a', '--5', '--b', '1'],
  ['--a', '1', '--b', '--a'],

  // --- competing error kinds -------------------------------------------------
  ['-a', '1', '--b', '1'],
  ['-a', '1', '-b', '1'],
  ['--a', '1', '--c', '3'],
  ['--c', '3'],
  ['--a', 'x', '--c', '3'],
  ['--a', 'x', '--b', 'y'],
  ['--a', 'x'],
  ['positional', '--c'],
];

// ---------------------------------------------------------------------------
// display helpers
// ---------------------------------------------------------------------------
function asciiQuote(s) {
  let out = '"';
  for (const ch of s) {
    const c = ch.codePointAt(0);
    if (ch === '"') out += '\\"';
    else if (ch === '\\') out += '\\\\';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else if (ch === '\r') out += '\\r';
    else if (c >= 0x20 && c <= 0x7e) out += ch;
    else if (c <= 0xff) out += '\\x' + c.toString(16).padStart(2, '0');
    else if (c <= 0xffff) out += '\\u' + c.toString(16).padStart(4, '0');
    else out += '\\u{' + c.toString(16) + '}';
  }
  return out + '"';
}

export function asciiArgv(argv) {
  return '[' + argv.map(asciiQuote).join(', ') + ']';
}

function diffBlock(label, expected, actual) {
  if (expected === actual) return '';
  const e = expected.split('\n');
  const a = actual.split('\n');
  const lines = [`    --- expected ${label}`, `    +++ actual   ${label}`];
  const n = Math.max(e.length, a.length);
  for (let i = 0; i < n; i++) {
    const el = i < e.length ? e[i] : null;
    const al = i < a.length ? a[i] : null;
    if (el === al) {
      lines.push('      ' + asciiQuote(el));
    } else {
      if (el !== null) lines.push('    - ' + asciiQuote(el));
      if (al !== null) lines.push('    + ' + asciiQuote(al));
    }
  }
  return lines.join('\n');
}

function describeStatus(res) {
  if (res.error && res.error.code === 'ETIMEDOUT') return 'TIMEOUT';
  if (res.signal) return `signal:${res.signal}`;
  if (res.status === null || res.status === undefined) {
    return res.error ? `spawn-error:${res.error.code || res.error.message}` : 'null';
  }
  return String(res.status);
}

// ---------------------------------------------------------------------------
// runner
// ---------------------------------------------------------------------------
function run(cmd, args) {
  const res = spawnSync(cmd, args, {
    encoding: 'utf8',
    shell: false,
    timeout: 10000,
    maxBuffer: 16 * 1024 * 1024,
  });
  return {
    stdout: res.stdout === null || res.stdout === undefined ? '' : res.stdout,
    stderr: res.stderr === null || res.stderr === undefined ? '' : res.stderr,
    status: describeStatus(res),
  };
}

export function main() {
  const entry = process.argv[2];
  if (!entry) {
    process.stderr.write('usage: node difftest.mjs <path-to-entry.mjs>\n');
    process.exit(2);
  }
  const targetProg = basename(entry);

  // The reference derives its prog name from argv[0]; the port derives its own.
  // Normalize ONLY that token, nothing else.
  const normalize = (s) => s.split(REFERENCE_PROG).join(targetProg);

  let passed = 0;
  const failures = [];

  for (let i = 0; i < CASES.length; i++) {
    const argv = CASES[i];
    const ref = run(REFERENCE, argv);
    const got = run(process.execPath, [entry, ...argv]);

    const expected = {
      stdout: normalize(ref.stdout),
      stderr: normalize(ref.stderr),
      status: ref.status,
    };

    const ok =
      expected.stdout === got.stdout &&
      expected.stderr === got.stderr &&
      expected.status === got.status;

    if (ok) {
      passed++;
      process.stdout.write('.');
    } else {
      process.stdout.write('F');
      const parts = [];
      parts.push(`FAIL #${i + 1} argv=${asciiArgv(argv)}`);
      if (expected.status !== got.status) {
        parts.push(`    status: expected ${expected.status}, actual ${got.status}`);
      }
      const so = diffBlock('stdout', expected.stdout, got.stdout);
      if (so) parts.push(so);
      const se = diffBlock('stderr', expected.stderr, got.stderr);
      if (se) parts.push(se);
      failures.push(parts.join('\n'));
    }
  }

  process.stdout.write('\n');
  if (failures.length) {
    process.stdout.write('\n' + failures.join('\n\n') + '\n\n');
  }
  process.stdout.write(`RESULT: ${passed}/${CASES.length} passed\n`);
  process.exit(passed === CASES.length ? 0 : 1);
}

const invokedDirectly =
  process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (invokedDirectly) main();

