import { spawnSync } from 'node:child_process';
const R = '/workspace/dataset/test11_executable';
const cp = (...c) => String.fromCodePoint(...c);
const probes = [
  ['arabic 5_6 -> expect 56', ['--a', cp(0x0665) + '_' + cp(0x0666), '--b', '0']],
  ['astral 9+MATH5 -> expect 95', ['--a', '9' + cp(0x1d7dd), '--b', '0']],
  ['ctrl U+0001 repr -> expect \\x01', ['--a', cp(0x0001), '--b', '1']],
  ['NBSP alone repr -> expect \\xa0', ['--a', cp(0x00a0), '--b', '1']],
  ['deseret printable U+10400', ['--a', cp(0x10400), '--b', '1']],
  ["both ' and \" -> expect 'both\\'and\"'", ['--a', 'both\'and"', '--b', '1']],
  ["it's -> expect \"it's\"", ['--a', "it's", '--b', '1']],
  ['ZWSP+5 -> expect invalid', ['--a', cp(0x200b) + '5', '--b', '1']],
  ['OGHAM+5 -> expect valid 5', ['--a', cp(0x1680) + '5', '--b', '0']],
];
for (const [name, argv] of probes) {
  const r = spawnSync(R, argv, { encoding: 'utf8' });
  console.log('== ' + name + '  status=' + r.status);
  if (r.stdout) console.log('   OUT lines: ' + JSON.stringify(r.stdout.trim().split('\n').join('|')));
  if (r.stderr) console.log('   ERR: ' + JSON.stringify(r.stderr.split('\n')[1]));
}

import { readFileSync } from 'node:fs';
import { CASES, asciiJson } from '/tmp/difftest.mjs';

const doc = readFileSync('/tmp/difftest-cases.md', 'utf8');
// Collect the numbered case rows: | N | `argv` |
const rows = new Map();
for (const line of doc.split('\n')) {
  const m = /^\|\s*(\d+)\s*\|\s*`(.*)`\s*\|$/.exec(line);
  if (m) rows.set(Number(m[1]), m[2]);
}
console.log('rows found in doc:', rows.size, ' CASES:', CASES.length);

let bad = 0;
for (let i = 0; i < CASES.length; i++) {
  const expect = asciiJson(CASES[i].argv);
  const got = rows.get(i + 1);
  if (got === undefined) { console.log(`MISSING row ${i + 1}: ${expect}`); bad++; continue; }
  if (got !== expect) { console.log(`MISMATCH ${i + 1}:\n  doc:  ${got}\n  code: ${expect}`); bad++; }
}
for (const n of rows.keys()) {
  if (n < 1 || n > CASES.length) { console.log(`EXTRA row ${n}`); bad++; }
}
console.log(bad === 0 ? 'DOC IN SYNC' : `DOC OUT OF SYNC (${bad} problems)`);
